var EXTRA=[{"dot": "gray", "j": "Bone Joint Res", "h": "Difetto tibiale mediale in osso osteoporotico: meglio blocco con cono centrale", "v": "Simulazione a elementi finiti, non pazienti: nell'osso sano entrambe le ricostruzioni sono stabili, in quello osteoporotico il cono asimmetrico perde stabilità; vale per un solo tipo di difetto.", "pmid": "42899483", "doi": "10.1302/2046-3758.1510.BJR-2026-0180.R1", "temi": ["protesi", "revisione", "difetto tibiale", "elementi finiti"]}, {"dot": "gray", "j": "Bone Joint Res", "h": "Difetti tibiali AORI III: augment stampato in 3D con stelo, serie di quattro donne", "v": "Augment su misura con protesi di superficie e follow-up minimo di circa venti mesi, con un'infezione periprotesica sul lato femorale; la serie è troppo piccola per giudicare la tecnica.", "pmid": "42896852", "doi": "10.1302/2046-3758.1510.BJR-2025-0729.R1", "temi": ["protesi", "revisione", "stampa 3D", "difetto tibiale"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Kujala e HSS Patella dopo protesi: soglie di cambiamento clinicamente rilevante", "v": "Studio retrospettivo su protesi totali con almeno due anni di controllo, che ricava MCID, SCB e PASS rispetto a una scala di cambiamento percepito; aiuta a leggere i punteggi rotulei e non riguarda una tecnica.", "pmid": "42894597", "doi": "10.1007/s43465-026-01867-2", "temi": ["protesi", "rotula", "punteggi", "MCID"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Deformità in varo: la navigazione misura più varo delle radiografie in piedi", "v": "Su protesi totali navigate la differenza fra le due misure cresce con la deformità; conta per chi pianifica sulle radiografie, ma non confronta esiti clinici.", "pmid": "42894609", "doi": "10.1007/s43465-026-01893-0", "temi": ["protesi", "navigazione", "allineamento", "varo"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Protesi non cementata oltre i settant'anni: esiti riferiti a un anno non peggiori", "v": "Registro prospettico di un'istituzione con controllo a un anno; la sopravvivenza dell'impianto non è valutata, quindi il messaggio sull'età vale solo a breve termine.", "pmid": "42894525", "doi": "10.1007/s43465-026-01883-2", "temi": ["protesi", "cementazione", "età", "PROM"]}, {"dot": "gray", "j": "Arch Orthop Trauma Surg", "h": "Revisione asettica della protesi: VES e PCR non distinguono la causa", "v": "Coorte retrospettiva monocentrica: marcatori sistemici e conta cellulare sinoviale non variano fra le cause; solo l'usura del polietilene mostra un profilo di macrofagi, a titolo esplorativo.", "pmid": "42902091", "doi": "10.1007/s00402-026-06536-5", "temi": ["protesi", "revisione", "liquido sinoviale", "usura"]}, {"dot": "gray", "j": "Microscopy (Oxf)", "h": "Il LCA umano al microscopio: fibrille che attraversano la cartilagine verso la tibia", "v": "Studio istologico su pochi campioni di pazienti con rottura del LCA o artrosi; descrive l'inserzione tibiale, senza esiti clinici.", "pmid": "42895845", "doi": "10.1093/jmicro/dfag036", "temi": ["LCA", "istologia", "inserzione tibiale", "collagene"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Lesione multilegamentosa con frattura tibiale consolidata male: osteotomia e legamenti a tempi", "v": "Caso singolo di un ventenne con LCA, LCP e angolo posterolaterale: prima si corregge l'osso, poi i legamenti in più tempi; un caso illustra la sequenza e non la dimostra.", "pmid": "42894507", "doi": "10.1007/s43465-026-01784-4", "temi": ["multilegamentose", "osteotomia", "angolo posterolaterale", "frattura tibiale"]}, {"dot": "gray", "j": "Cartilage", "h": "Perdita di estensione e cartilagine femorale: nell'Osteoarthritis Initiative più osso scoperto", "v": "Analisi trasversale con risonanza in pazienti con artrosi: associazione e non causalità, senza indicazioni chirurgiche.", "pmid": "42863822", "doi": "10.1177/19476035261498127", "temi": ["cartilagine", "artrosi", "estensione", "risonanza"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Osteotomia fibulare prossimale per l'artrosi mediale: revisione narrativa, prove ancora deboli", "v": "Dolore e funzione migliorano e lo spazio mediale si allarga in studi per lo più retrospettivi e piccoli; meccanismo non chiarito e confronto con altre osteotomie assente.", "pmid": "42894541", "doi": "10.1007/s43465-026-01862-7", "temi": ["osteotomia", "artrosi mediale", "fibula", "revisione narrativa"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Menischi nell'artrosi: meno collagene nel mediale che nel laterale, in funzione della gravità", "v": "Studio istologico trasversale su menischi prelevati durante protesi: descrive il tessuto già degenerato e non indica come intervenire.", "pmid": "42894518", "doi": "10.1007/s43465-026-01796-0", "temi": ["menisco", "collagene", "artrosi", "istologia"]}];
var SCOPERTE=[{"t": "Ortesi del ginocchio stampate in 3D con fibra di bambù: il materiale si può degradare", "v": "Studio di ingegneria dei materiali (Materials, Zhejiang): composito di acido polilattico, PBAT e fibra di bambù stampato a granuli, con un'ortesi dimostrativa di 243 grammi. Vale la deviazione perché mostra che cosa si prova fuori dalle plastiche di origine petrolifera; è un esperimento di laboratorio, senza pazienti né prove cliniche.", "pmid": "42882719", "doi": "10.3390/ma19194221", "temi": ["ortesi", "stampa 3D", "biomateriali", "bioingegneria"]}, {"t": "Capacità aerobica innata e salute dell'articolazione: nei ratti a bassa capacità, più danno cartilagineo", "v": "Modello animale (J Orthop Res, Calgary): ratti selezionati per alta o bassa capacità aerobica, con dieta ricca di grassi e zuccheri o normale; quelli a bassa capacità hanno punteggi di Mankin più alti, più infiammazione e iperglicemia. Vale la deviazione perché sposta lo sguardo dal carico meccanico al metabolismo; è un ratto e non dice che cosa fare nel paziente.", "pmid": "42896009", "doi": "10.1002/jor.70299", "temi": ["cartilagine", "metabolismo", "artrosi", "modello animale"]}];
var SOC={"1": {"video": "Cartilagine del ginocchio: l'età o il peso contano per l'esito dell'intervento? Una revisione sistematica coreana ha riunito trentuno lavori sulle diverse tecniche di riparazione.\n\nDopo le microfratture un'età più alta si è associata a risultati meno buoni in due analisi; per la dimensione della lesione e per le altre tecniche i risultati cambiano da studio a studio e nessun fattore è confermato.\n\nQuasi tutte le analisi hanno un rischio metodologico alto e alcune coorti si ripetono: non si possono fissare soglie di età, peso o dimensione del difetto.\nFonte: PubMed, PMID 42902365.", "linkedin": "Riparazione della cartilagine del ginocchio: l'età o il peso decidono l'esito? Una revisione sistematica coreana di 31 lavori (Knee Surgery & Related Research, 2026) non trova un fattore valido per tutte le tecniche. Dopo le microfratture un'età più alta si associa a risultati peggiori in due analisi.\n\nIl limite: quasi tutte le analisi hanno un rischio metodologico alto e alcune coorti si ripetono.\nFonte: PubMed, PMID 42902365.", "instagram": "Cartilagine del ginocchio\n\nDopo le microfratture l'età più alta si associa a risultati meno buoni, ma nessun fattore regge fra le tecniche.\n\nQuasi tutte le analisi hanno un rischio metodologico alto.\nFonte: PubMed, PMID 42902365.", "pazienti": "Cartilagine del ginocchio: età e peso, da soli, non bastano a prevedere come andrà l'intervento. Una revisione di 31 studi ha cercato i fattori che contano.\n\nDopo l'intervento con microfratture, chi è più anziano tende ad avere risultati meno buoni, ma gli studi sono diversi fra loro e non c'è una regola valida per tutti.\n\nGli studi hanno limiti importanti: la scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42902365."}};
var SOCV={"1": {"video": {"chir": ["Fattori prognostici dopo la riparazione della cartilagine del ginocchio: revisione sistematica coreana su Knee Surgery & Related Research, 31 report, senza metanalisi; l'eterogeneità impone di sintetizzare per procedura, contesto, esito e follow-up.", "Dopo microfratture l'età maggiore si associa a esiti peggiori in due analisi aggiustate: OR 0,61 per il MCID e 0,86 per il PASS a 24 mesi, intervalli non riportati. Dimensione della lesione: risultati discordi. Fra ACI/MACI, trapianto osteocondrale e impianti cellulari nessun fattore costante.", "Limiti: 29 analisi su 37 ad alto rischio di bias, nessuna a basso; coorti sovrapposte, quindi la somma di 13.022 non è un numero di pazienti. Le prove non sostengono soglie universali di età, BMI o dimensione del difetto.\nFonte: PubMed, PMID 42902365."], "misto": ["Dopo la riparazione della cartilagine del ginocchio, quali caratteristiche del paziente prevedono come andrà? Una revisione sistematica coreana ha riunito trentuno lavori sulle diverse tecniche.", "Dopo le microfratture, un'età più alta si è associata a risultati peggiori in due analisi; per la dimensione della lesione e per le altre tecniche i risultati cambiano da studio a studio e nessun fattore è confermato.", "Quasi tutte le analisi hanno un rischio metodologico alto e alcune coorti si ripetono: la revisione non permette di fissare soglie di età, peso o dimensione del difetto per scegliere o escludere un trattamento.\nFonte: PubMed, PMID 42902365."], "pazienti": ["Cartilagine del ginocchio: l'età o il peso contano per l'esito dell'intervento? Una revisione di trentuno studi ha cercato una risposta.", "Dopo l'intervento con microfratture, chi è più anziano tende ad avere risultati meno buoni, ma gli studi sono diversi fra loro e non c'è una regola valida per tutti.", "Gli studi hanno limiti importanti: nessuna età o peso, da soli, bastano a decidere se un intervento è adatto. La scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42902365."]}, "linkedin": {"chir": ["Fattori prognostici dopo riparazione della cartilagine del ginocchio (Knee Surg Relat Res, 2026): revisione sistematica senza metanalisi, 31 report, 37 unità di analisi secondo QUIPS.", "Microfratture isolate: l'età maggiore si associa a esiti peggiori in due analisi aggiustate (OR 0,61 per il MCID, 0,86 per il PASS a 24 mesi; intervalli non riportati). Dimensione della lesione e altre procedure: associazioni dipendenti da esito e follow-up.", "Limiti: 29 unità su 37 ad alto rischio di bias, nessuna a basso; coorti sovrapposte, 13.022 non è un numero di pazienti; nessuna soglia universale.\nFonte: PubMed, PMID 42902365."], "misto": ["Riparazione della cartilagine del ginocchio: l'età o il peso decidono l'esito? Una revisione sistematica coreana di 31 lavori (Knee Surgery & Related Research, 2026) non trova un fattore valido per tutte le tecniche.", "Dopo le microfratture un'età più alta si associa a risultati peggiori in due analisi; per dimensione della lesione e per altre tecniche i risultati cambiano da studio a studio.", "Il limite: quasi tutte le analisi hanno un rischio metodologico alto e alcune coorti si ripetono; non si possono fissare soglie per scegliere o escludere un trattamento.\nFonte: PubMed, PMID 42902365."], "pazienti": ["Cartilagine del ginocchio: età e peso bastano a prevedere come andrà l'intervento? Una revisione di 31 studi dice di no.", "Dopo le microfratture chi è più anziano tende ad avere risultati meno buoni, ma gli studi sono diversi fra loro.", "Gli studi hanno limiti importanti e non permettono di dare regole uguali per tutti: la scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42902365."]}, "instagram": {"chir": ["Cartilagine: prognosi dopo riparazione", "Microfratture: età maggiore, esito peggiore in 2 analisi aggiustate (OR 0,61 e 0,86), intervalli assenti.", "29/37 analisi ad alto rischio di bias; nessuna soglia universale.\nFonte: PubMed, PMID 42902365."], "misto": ["Cartilagine del ginocchio", "Dopo le microfratture l'età più alta si associa a risultati meno buoni, ma nessun fattore regge fra le tecniche.", "Quasi tutte le analisi hanno un rischio metodologico alto.\nFonte: PubMed, PMID 42902365."], "pazienti": ["Cartilagine del ginocchio", "Età e peso, da soli, non bastano a prevedere come andrà l'intervento: lo dice una revisione di 31 studi.", "Gli studi hanno limiti: la scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42902365."]}, "reel": {"chir": ["[Testo a schermo] Cartilagine: chi va meglio?", "31 report, 37 analisi: nessun fattore costante.", "Età: peggio dopo microfratture. Bias alto.\nFonte: PubMed, PMID 42902365."], "misto": ["[Testo a schermo] Cartilagine: chi va meglio?", "31 studi: nessun fattore vale per tutti.", "Più anziani, meno bene dopo microfratture.\nFonte: PubMed, PMID 42902365."], "pazienti": ["[Testo a schermo] Cartilagine del ginocchio", "Età e peso non bastano a prevedere l'esito.", "La scelta spetta al chirurgo.\nFonte: PubMed, PMID 42902365."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Cartilagine #Ginocchio", "instagram": "#ortopedia #ginocchio #cartilagine #microfratture #chirurgiadelginocchio #medicinadellosport #riabilitazione #ortopediaticino #ticino #medicinabasatasulleprove #salute", "kw": "cartilagine del ginocchio, microfratture, riparazione della cartilagine, ginocchio, chirurgia artroscopica"}};
var NLB={"1": {"prof": ["Cartilagine del ginocchio: l'età pesa dopo le microfratture, nessun altro fattore regge", "Revisione sistematica coreana senza metanalisi (Knee Surg Relat Res, 2026; 31 report, 37 unità di analisi). Dopo microfratture isolate l'età maggiore si associa a esiti peggiori in due analisi aggiustate (OR 0,61 per il MCID e 0,86 per il PASS a 24 mesi, intervalli non riportati); la dimensione della lesione dà risultati discordi; per ACI/MACI, trapianto osteocondrale e impianti cellulari le associazioni dipendono da esito e follow-up.", "Nota critica: 29 unità su 37 ad alto rischio di bias e nessuna a basso; coorti sovrapposte, quindi la somma di 13.022 non è un numero di pazienti; gli autori non trovano soglie universali di età, BMI o dimensione del difetto."], "mix": ["Riparazione della cartilagine: età o peso decidono l'esito? Le prove non bastano", "Una revisione sistematica coreana ha riunito 31 lavori sulle diverse tecniche di riparazione della cartilagine. Dopo le microfratture, un'età più alta si è associata a risultati peggiori in due analisi; per la dimensione della lesione e per le altre tecniche i risultati cambiano da studio a studio e nessun fattore è confermato in modo costante.", "Nota sul limite: quasi tutte le analisi hanno un rischio metodologico alto e alcune coorti si ripetono; non si possono fissare soglie di età, peso o dimensione del difetto."], "paz": ["Cartilagine del ginocchio: età e peso, da soli, non bastano a dire come andrà l'intervento", "Una revisione di 31 studi ha cercato quali caratteristiche del paziente prevedono il risultato dopo la riparazione della cartilagine. Dopo l'intervento con microfratture, chi è più anziano tende ad avere risultati meno buoni, ma gli studi sono molto diversi fra loro e non c'è una regola valida per tutti.", "Gli studi hanno limiti importanti: nessuna età o peso, da soli, bastano a decidere se un intervento è adatto. La scelta spetta al chirurgo, caso per caso."], "kw": "cartilagine, ginocchio, microfratture, riparazione della cartilagine"}, "2": {"prof": ["Osteotomia d'apertura a 12 anni: conversione in protesi nel 22,2% dei KL4 contro il 6,9%", "Coorte retrospettiva giapponese (Knee Surg Relat Res, 2026; 274 ginocchia, follow-up medio 12,5 ± 2,6 anni). Revisione in 43 ginocchia: 22,2% nei KL4 contro 6,9% nei KL2-3 (p<0,01); conservazione a 10 anni 90,5% contro 96,5% (log-rank p=0,006). Nei KL4 il %MA postoperatorio si associa alla revisione (OR 0,94; IC 95% 0,91-0,98).", "Nota critica: livello IV, centro singolo; nei KL2-3 le revisioni sono circa 8 (calcolo dalle percentuali), troppo poche per la regressione, che gli autori definiscono esplorativa."], "mix": ["Osteotomia della tibia a 12 anni: la protesi serve più spesso quando l'artrosi è avanzata", "In uno studio giapponese su 274 ginocchia operate di osteotomia tibiale d'apertura e seguite in media 12 anni, è stato necessario sostituire l'articolazione con una protesi nel 22,2% dei casi con artrosi avanzata (grado 4) e nel 6,9% di quelli con artrosi iniziale o intermedia. A 10 anni l'articolazione era conservata nel 90,5% contro il 96,5%.", "Nota sul limite: studio sul passato, in un solo centro; le analisi sui fattori legati alla protesi nei gruppi meno numerosi sono esplorative."], "paz": ["Osteotomia del ginocchio: a dieci anni l'articolazione è conservata in oltre nove casi su dieci", "In uno studio su 274 ginocchia operate con osteotomia della tibia e seguite in media 12 anni, a 10 anni l'articolazione era ancora quella naturale nel 90,5% dei casi con artrosi avanzata e nel 96,5% di quelli con artrosi iniziale o intermedia.", "Lo studio guarda al passato e riguarda un solo centro giapponese: i risultati possono essere diversi in altri pazienti."], "kw": "osteotomia tibiale, ginocchio, artrosi, protesi del ginocchio"}, "3": {"prof": ["Menisco discoide di Wrisberg: radice ricreata con ancora senza nodi, risparmiando la fisi", "Nota tecnica (Arthrosc Tech, 2026): saucerizzazione, stabilizzazione periferica all-inside e inside-out e ricostruzione della radice posteriore con una ancora senza nodi retensionabile al posto del tunnel transtibiale standard, per non rischiare la cartilagine di crescita; microfratture come aumento biologico.", "Nota critica: nessun esito, nessun controllo, numero di pazienti non riportato; dimostra la fattibilità, non il vantaggio."], "mix": ["Menisco discoide instabile in un giovane: radice fissata senza toccare la fisi", "Un gruppo di Washington descrive come ha trattato un menisco esterno a forma di disco senza gli attacchi posteriori, in un paziente con cartilagine di crescita ancora aperta: il menisco è stato rimodellato e la radice è stata fissata con un'ancora al posto del tunnel nell'osso della tibia.", "Nota sul limite: è la descrizione di una tecnica, senza risultati né confronti; non dice se sia meglio del tunnel."], "paz": ["Menisco discoide instabile in un ragazzo: una tecnica che rispetta la cartilagine di crescita", "Un gruppo di chirurghi descrive come hanno riparato un menisco esterno a forma di disco instabile in un giovane con la cartilagine di crescita ancora aperta, fissandolo con un'ancora invece che con un tunnel nell'osso della tibia.", "È la descrizione di una tecnica, senza risultati: non dice se sia più adatta di un'altra e la scelta spetta al chirurgo, caso per caso."], "kw": "menisco discoide, menisco laterale, adolescenti, chirurgia artroscopica"}, "4": {"prof": ["Elettrostimolazione dopo LCA in 20 atleti: Lysholm 86,56, ma mancano i dati dei controlli", "Studio comparativo cinese (Acta Bioeng Biomech, 2026; 20 atleti, 10 settimane). Nel gruppo con elettrostimolazione neuromuscolare Lysholm 86,56 ± 11,67, ACL-RSI 84,21 ± 5,32, flessione attiva 105,12 ± 9,87°. Gli autori parlano di esiti 'significativamente superiori' alla riabilitazione convenzionale.", "Nota critica: l'abstract non riporta i valori del gruppo di controllo né i p; 20 pazienti, assegnazione non descritta; il vantaggio dichiarato non è verificabile."], "mix": ["Elettrostimolazione dopo il crociato: studio piccolo, il confronto non è mostrato", "In uno studio su 20 atleti dopo ricostruzione del legamento crociato anteriore, l'elettrostimolazione dei muscoli associata alla riabilitazione ha dato, dopo 10 settimane, un punteggio di ginocchio (Lysholm) di 86,56 su 100. Gli autori scrivono che i risultati sono migliori di quelli della riabilitazione convenzionale.", "Nota sul limite: i dati del gruppo di confronto non compaiono nel riassunto e i pazienti sono pochi: il vantaggio non si può controllare."], "paz": ["Elettrostimolazione dopo il crociato: uno studio su 20 atleti, troppo piccolo per concludere", "In uno studio su 20 atleti operati di legamento crociato anteriore, l'elettrostimolazione dei muscoli della coscia, aggiunta alla riabilitazione, è stata provata per 10 settimane. Gli autori riferiscono risultati migliori della sola riabilitazione.", "Sono pochi pazienti e il confronto non è mostrato nei dati disponibili: servono studi più ampi prima di trarre conclusioni."], "kw": "legamento crociato anteriore, riabilitazione, elettrostimolazione, ginocchio"}, "5": {"prof": ["Rottura del quadricipite: fori angolati più resistenti dei longitudinali, come le ancore", "Studio biomeccanico su cadavere (J Exp Orthop, 2026; 21 rotule, 7 per gruppo): carico di rottura 472,7 ± 22,4 N con fori angolati contro 344,8 ± 108,8 N con fori longitudinali (p<0,05); ancore 438,9 ± 77,4 N, senza differenza significativa; allungamento ciclico minore con le ancore che con i fori longitudinali (p<0,01).", "Nota critica: 7 campioni per gruppo, stabilità primaria e non guarigione; nessuna differenza fra fori angolati e ancore non equivale a equivalenza."], "mix": ["Tendine del quadricipite rotto: un modo di fissarlo all'osso regge di più in laboratorio", "In un esperimento su 21 rotule di cadavere, tre fori angolati nella rotula hanno resistito a un carico di rottura medio di 472,7 N, contro 344,8 N dei fori dritti; le ancore hanno dato 438,9 N, senza una differenza sicura rispetto agli altri due metodi.", "Nota sul limite: è un esperimento su osso di cadavere, con pochi campioni; non dice come vanno i pazienti."], "paz": ["Rottura del tendine sopra la rotula: in laboratorio un metodo di fissazione regge di più", "In un esperimento su ossa di cadavere, un modo di fissare il tendine alla rotula con fori inclinati ha tenuto più di quello con fori dritti, e quanto le ancore.", "È una prova di laboratorio con pochi campioni: non dice come vanno i pazienti."], "kw": "tendine quadricipitale, rottura del quadricipite, rotula, ginocchio"}, "6": {"prof": ["Protesi robotica con allineamento funzionale: la rotazione del femore segue la tensione mediale", "Studio osservazionale di un chirurgo (J Robot Surg, 2026; 65 ginocchia varo): ρ di Spearman 0,571 (p<0,001) fra tensione mediale e rotazione scelta; 0,343° per mm (R² 0,257; IC 95% 0,194-0,492). Rilascio lieve in 64/65, asimmetria finale entro 1 mm in 53/58 (91,4%) in estensione e flessione.", "Nota critica: un solo chirurgo, nessun esito clinico né controllo; sistema robotico non nominato nell'abstract; gli autori non dimostrano benefici della simmetria sotto 1 mm."], "mix": ["Protesi con robot: come un chirurgo sceglie la rotazione del femore in base alla tensione", "In 65 ginocchia con gamba a O operate di protesi totale con robot e allineamento funzionale, più il lato interno era stretto con il ginocchio piegato, più il chirurgo ruotava il componente del femore: circa un terzo di grado per ogni millimetro di tensione. I rilasci dei tessuti sono stati lievi quasi sempre.", "Nota sul limite: descrive le scelte di un solo chirurgo e non mostra se i pazienti stiano meglio."], "paz": ["Protesi di ginocchio con robot: uno studio descrive come si regola la rotazione del femore", "In 65 ginocchia operate con protesi totale e robot, il chirurgo ha ruotato il componente del femore in base a quanto era stretto il lato interno del ginocchio, riuscendo quasi sempre a bilanciare il ginocchio con rilasci lievi.", "Lo studio descrive il lavoro di un solo chirurgo e non dice se i pazienti stiano meglio: i risultati dipendono dal caso."], "kw": "protesi totale di ginocchio, chirurgia robotica, allineamento, ginocchio"}, "7": {"prof": ["Femore in una coorte spagnola: con riferimenti fissi la protesi cade in varo nel 74,7% dei casi", "Studio trasversale su TC di 318 pazienti con artrosi (Rev Esp Cir Ortop Traumatol, 2026): AA-MA 6,0° ± 0,9°, PCA-TEA 3,1° ± 1,8°, LDFA nativo 87,3° ± 2,9°. Simulando 5° di valgo e 3° di rotazione esterna fissi, 74,7% dei componenti in varo e 46,1% in rotazione interna.", "Nota critica: simulazione su TC, nessun impianto reale né esito clinico; coorte di un solo paese."], "mix": ["Osso del femore: l'anatomia varia, e un solo angolo per tutti porta spesso fuori bersaglio", "In una TC di 318 pazienti spagnoli con artrosi, gli angoli del femore variano molto da persona a persona; usando per tutti gli stessi riferimenti fissi, in 3 casi su 4 circa il componente della protesi finirebbe inclinato verso l'interno rispetto all'obiettivo.", "Nota sul limite: è una simulazione al computer su immagini, non operazioni reali."], "paz": ["Protesi di ginocchio: ogni femore è diverso, il posizionamento va misurato caso per caso", "In una ricerca su immagini di 318 pazienti si è visto che la forma dell'osso della coscia varia molto da persona a persona, e che usare gli stessi riferimenti per tutti può portare la protesi lontano dalla posizione prevista.", "È una simulazione al computer: non riguarda i risultati delle operazioni reali."], "kw": "protesi di ginocchio, femore, allineamento, anatomia"}, "8": {"prof": ["Quadricipite rotto dopo protesi: 11 studi, 132 ginocchia, complicanze 17,8%, nessuno standard", "Revisione sistematica PRISMA (Indian J Orthop, 2026; 10 studi retrospettivi, 1 prospettivo): sutura semplice in 49 ginocchia, V-Y in 46, rete in 10, innesto in 19, conservativo in 8; complicanze 17,8%, soprattutto nuova rottura e infezione. Riparazione o ricostruzione migliorano il deficit di estensione.", "Nota critica: serie retrospettive e piccole, nessun confronto diretto fra le tecniche, intervalli non riportati."], "mix": ["Quadricipite rotto dopo una protesi: la riparazione aiuta, ma non c'è un metodo di riferimento", "Una revisione di 11 studi su 132 ginocchia con tendine del quadricipite rotto dopo protesi riferisce che riparazione o ricostruzione migliorano la capacità di stendere il ginocchio. Circa una volta su sei compaiono complicanze, soprattutto nuova rottura e infezione.", "Nota sul limite: gli studi sono quasi tutti retrospettivi e piccoli, e non permettono di dire quale tecnica sia preferibile."], "paz": ["Tendine rotto dopo una protesi di ginocchio: l'intervento aiuta a stendere di nuovo la gamba", "Una revisione di 11 studi su 132 ginocchia con tendine rotto dopo la protesi indica che l'intervento migliora la capacità di stendere il ginocchio, ma può avere complicanze.", "Gli studi sono pochi e piccoli: la scelta del trattamento spetta al chirurgo, caso per caso."], "kw": "quadricipite, protesi di ginocchio, rottura del tendine, ginocchio"}, "9": {"prof": ["Dolore femororotuleo negli adolescenti: la pliometria in acqua riduce dolore e disabilità", "RCT su 56 adolescenti (J Rehabil Med, 2026; 12 settimane): dolore p=0,004 (η²p 0,14), coppia del quadricipite a 120°/s p=0,006 e a 180°/s p=0,008, ischiocrurali p=0,007 e p=0,023, disabilità p=0,03, qualità di vita p=0,023.", "Nota critica: effetti da piccoli a medi, medie dei gruppi e soglie cliniche non riportate nell'abstract; nessun follow-up dopo le 12 settimane."], "mix": ["Dolore davanti al ginocchio negli adolescenti: gli esercizi in acqua riducono il dolore", "In uno studio randomizzato su 56 adolescenti con dolore femororotuleo, 12 settimane di esercizi di salto in acqua hanno ridotto il dolore e la disabilità e aumentato la forza dei muscoli della coscia più degli esercizi convenzionali.", "Nota sul limite: gli effetti sono da piccoli a medi, non si conosce il risultato dopo la fine del trattamento e non tutti i pazienti avevano l'età della pratica ambulatoriale."], "paz": ["Dolore davanti al ginocchio nei ragazzi: 12 settimane di esercizi in acqua l'hanno ridotto", "In uno studio su 56 ragazzi con dolore davanti al ginocchio, 12 settimane di esercizi di salto in piscina hanno ridotto il dolore e migliorato la forza più degli esercizi consueti.", "Lo studio è piccolo e non dice come stiano i ragazzi dopo la fine degli esercizi: la scelta spetta al fisioterapista e al medico, caso per caso."], "kw": "dolore femororotuleo, adolescenti, riabilitazione, ginocchio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surg Relat Res",h:"Cartilagine del ginocchio: dopo le microfratture l'età pesa, ma nessun fattore prognostico regge fra le procedure",v:"Revisione sistematica coreana senza metanalisi: 31 report sui fattori che predicono l'esito dopo la riparazione della cartilagine. Dopo microfratture isolate l'età maggiore si associa a esiti peggiori in due analisi aggiustate (OR 0,61 per il MCID e 0,86 per il PASS a 24 mesi; intervalli non riportati). 29 delle 37 unità di analisi sono ad alto rischio di bias, nessuna a basso; nessun fattore è confermato in modo costante e le prove non sostengono soglie universali.",ax:"Han, Jung, Chung, Moon, Jung, Baik, Koo, Kim",date:"ott 2026",meta:"revisione sistematica senza metanalisi, livello IV (di studi I-IV), 31 report (somma delle numerosità 13.022, coorti sovrapposte)",pmid:'42902365',doi:'10.1186/s43019-026-00350-4',journal:"Knee surgery & related research",authors:"Han JH, Jung M, Chung K, Moon HS, Jung SH, Baik SH, Koo J, Kim SH",design:"Revisione sistematica (PROSPERO CRD420251249852, PRISMA 2020; Yonsei, Seul) su PubMed, Embase, Cochrane Library e Google Scholar fino al 29 agosto 2026, più citazioni a ritroso e in avanti: 1691 record, 704 dopo i duplicati, 59 a testo completo, 31 inclusi. Rischio di bias con QUIPS sulle singole analisi (MINORS e RoB 2 solo a livello di disegno); sintesi senza metanalisi, per contesto di malattia, procedura, fattore, esito e follow-up. Parte dei metodi aggiunta dopo la registrazione del protocollo. Letto il testo completo (PMC).",pop:"31 report su adulti con difetto focale (26), lesione associata ad artrosi (4) o diagnosi osteocondrale mista (1); 1 di livello I, 13 di livello III, 17 di livello IV. Procedure: stimolazione midollare isolata o con adiuvante biologico, impianto cellulare (ACI/MACI, cellule mesenchimali, SVF), trapianto osteocondrale, scaffold. La somma delle numerosità, 13.022, non è un numero di pazienti distinti per la sovrapposizione delle coorti.",results:"37 unità di analisi: 29 ad alto rischio di bias, 8 a rischio moderato, nessuna a basso (QUIPS). Microfratture isolate: con l'età maggiore minori probabilità di MCID (OR 0,61) e di PASS (OR 0,86) a 24 mesi nell'analisi aggiustata di Chahla e minor miglioramento di Lysholm a lungo termine in quella di Steadman (B standardizzato −0,299; p=0,011); intervalli di confidenza non riportati in entrambe. Nel braccio microfratture di Vanlauwe, rischio di fallimento a 5 anni nelle donne non aggiustato RR 4,78 (IC 95% 1,49-15,62). Dimensione della lesione: risultati discordi fra esiti e follow-up.",concl:"Gli autori: i fattori emersi sono associazioni candidate, legate a procedura, contesto di malattia, esito e follow-up; le prove non sostengono soglie cliniche universali né differenze di effetto prognostico fra le procedure.",limits:"29 unità su 37 ad alto rischio di bias, nessuna a basso; nessun grado di certezza assegnato · coorti sovrapposte (Kreuz, Yonsei, Ramkumar, HSS) e intervalli di confidenza spesso assenti: associazioni non indipendenti, non replicazioni · metodi aggiunti dopo la registrazione, solo studi in inglese, strategia di ricerca senza revisione PRESS.",perte:"Verde: tocca la tua cartilagine, ma nessuna tua procedura è nominata. AMIC con Chondro-Gide e minced cartilage con AutoCart non compaiono nel testo; la categoria vicina è la stimolazione midollare con adiuvante biologico: non direttamente trasferibile. Il dato utile è che l'età è l'unico segno concorde dopo microfratture (due analisi aggiustate, alto rischio di bias) e che resa condrocitaria e tempo di raddoppio, nell'ACI, cambiano da studio a studio: tocca di striscio la T5 (variabilità del tessuto di partenza) ma non sul minced cartilage. Non muove le tensioni. Cosa fare: nulla da cambiare; con un paziente non usare soglie di età, BMI o dimensione del difetto come criterio di esclusione, perché la revisione dice che non reggono."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surg Relat Res",h:"Osteotomia tibiale d'apertura a 12 anni: conversione in protesi nel 22,2% dei KL4 contro il 6,9% dei KL2-3",v:"Coorte retrospettiva giapponese di 274 ginocchia con osteotomia tibiale alta mediale d'apertura e follow-up medio di 12,5 anni. Revisione (conversione in TKA o UKA) in 43 ginocchia: 22,2% nei KL4 contro 6,9% nei KL2-3 (p<0,01); conservazione dell'articolazione a 10 anni 90,5% contro 96,5% (log-rank p=0,006). Nei KL4 conta l'asse meccanico postoperatorio (OR 0,94 per unità di %MA; IC 95% 0,91-0,98).",ax:"Gomi, Chikaishi, Isozaki",date:"ott 2026",meta:"coorte retrospettiva, livello IV, 274 ginocchia (158 KL4, 116 KL2-3), follow-up medio 12,5 ± 2,6 anni",pmid:'42902441',doi:'10.1186/s43019-026-00351-3',journal:"Knee surgery & related research",authors:"Gomi N, Chikaishi N, Isozaki R",design:"Studio retrospettivo (Sakaide Kaisei Hospital e Università di Kagawa, Giappone) su osteotomia tibiale alta mediale d'apertura (OWHTO) con follow-up minimo di 10 anni. Endpoint: conversione in TKA o UKA. Esiti clinici (punteggio JOA) e radiografici; regressione logistica multivariata separata per i KL4 e per i KL2-3. Tipo di fissazione, correzione pianificata e pendenza tibiale non riportati nell'abstract. Letto solo l'abstract.",pop:"274 ginocchia, 158 KL4 e 116 KL2-3; età media 64,7 ± 7,2 anni; follow-up medio 12,5 ± 2,6 anni.",results:"Revisione in 43 ginocchia (15,7%): 22,2% nei KL4 contro 6,9% nei KL2-3 (p<0,01). Conservazione dell'articolazione a 10 anni 90,5% contro 96,5% (log-rank p=0,006). JOA da 60,6 prima dell'intervento a 91,0 alla rimozione della placca, poi calo graduale; JOA finale 71,6 nei KL4 contro 83,1 nei KL2-3 (p<0,001). KL4: %MA postoperatorio alla rimozione della placca associato alla revisione (OR 0,94; IC 95% 0,91-0,98; p=0,004). KL2-3, analisi esplorativa: progressione dell'angolo di convergenza della linea articolare (ΔJLCA) OR 3,31 (IC 95% 1,52-7,21; p=0,003), %MA non associato.",concl:"Gli autori: gli esiti a lungo termine differiscono per grado KL; i KL4 hanno più revisioni e la posizione della linea di carico postoperatoria si associa al rischio, mentre nei KL2-3 la revisione è rara e potrebbe seguire la convergenza della linea articolare piuttosto che l'allineamento.",limits:"Retrospettivo di livello IV, centro singolo, popolazione giapponese di 65 anni · nei KL2-3 le revisioni sono circa 8 (6,9% di 116, calcolo nostro): troppo poche per una regressione multivariata, che gli autori stessi chiamano esplorativa · ΔJLCA si misura durante il follow-up, quindi può essere conseguenza e non causa · pendenza tibiale e tecnica non riportate.",perte:"Verde: tocca le tue osteotomie, ma è l'apertura mediale in una popolazione anziana e spesso con artrosi avanzata; la pendenza tibiale non è nell'abstract, quindi non dice nulla sulle tue correzioni di slope. Il dato utile è che il KL4 non è un'esclusione, ma moltiplica per circa tre il rischio di conversione in protesi a 10 anni (22,2% contro 6,9%). Non muove le tensioni. Cosa fare: nulla da cambiare; nel colloquio con un paziente KL4 il numero da dare è circa 90% di articolazione conservata a 10 anni."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Arthrosc Tech",h:"Menisco laterale discoide di Wrisberg: radice ricreata con ancora senza nodi, per risparmiare la fisi",v:"Nota tecnica (MedStar Georgetown, Washington): saucerizzazione e ricostruzione anatomica della radice posteriore e delle inserzioni capsulari assenti, con una ancora senza nodi retensionabile al posto del tunnel transtibiale standard, per non rischiare la cartilagine di crescita. Stabilizzazione periferica all-inside e inside-out, microfratture come aumento biologico. Nessun esito riportato.",ax:"Rossettie, Hu, Griffin, Perraut, Murray",date:"ott 2026",meta:"nota tecnica, livello non applicabile, numero di pazienti non riportato",pmid:'42894727',doi:'10.1002/atn2.70319',journal:"Arthroscopy techniques",authors:"Rossettie S, Hu A, Griffin D, Perraut G, Murray R",design:"Descrizione chirurgica di una tecnica in un menisco laterale discoide variante di Wrisberg senza radice posteriore né attacchi capsulari laterali: saucerizzazione, riparazione della periferia (all-inside e inside-out), radice ricreata con ancora senza nodi 'anchor-first', microfratture. Numero di pazienti, età e follow-up non riportati nell'abstract. Letto solo l'abstract.",pop:"Non riportata nell'abstract; il testo parla di un menisco laterale discoide instabile in un paziente con fisi da risparmiare.",results:"Nessun risultato clinico, funzionale o per immagini riportato nell'abstract: non riportati, quindi nessun numero e nessun intervallo di confidenza.",concl:"Gli autori: l'approccio ricrea l'attacco della radice senza rischiare la cartilagine di accrescimento, con tensione regolabile, e ripristina la funzione di carico del menisco.",limits:"Nota tecnica senza esiti né controllo: dimostra la fattibilità, non il vantaggio · un menisco discoide di Wrisberg è un'anatomia rara e congenita, non una radice degenerativa o traumatica dell'adulto · la 'protezione della fisi' è un'affermazione degli autori, non misurata.",perte:"Verde: tocca la tua rifissazione della radice, ma per una lesione diversa. Qui la radice si ricrea con ancora e non con il tunnel transtibiale, in un menisco discoide e con fisi aperte; non confronta le due vie e non ha esito. Non mette in discussione la tua tecnica transtibiale sull'adulto; è un'alternativa descritta per i tuoi pazienti dai 14 anni con fisi ancora aperte. Non muove le tensioni. Cosa fare: nulla da cambiare."},{n:4,mono:"m-gray",dot:"gray",sec:"res",j:"Acta Bioeng Biomech",h:"Elettrostimolazione dopo LCA in 20 atleti: Lysholm 86,56, ma i dati dei controlli non ci sono",v:"Studio comparativo cinese su 20 atleti dopo ricostruzione del LCA, 10 settimane di riabilitazione con o senza elettrostimolazione neuromuscolare. Nel gruppo trattato Lysholm 86,56 ± 11,67 e punteggio di rientro allo sport (ACL-RSI) 84,21 ± 5,32; gli autori scrivono 'significativamente superiori', ma i valori del gruppo di controllo e i p non sono nell'abstract.",ax:"Du, Liu",date:"ott 2026",meta:"studio comparativo, livello non riportato, 20 atleti, 10 settimane",pmid:'42885196',doi:'10.37190/abb/218840',journal:"Acta of bioengineering and biomechanics",authors:"Du J, Liu H",design:"Venti atleti sottoposti a ricostruzione del LCA, assegnati a elettrostimolazione neuromuscolare più riabilitazione o a riabilitazione convenzionale per 10 settimane; Lysholm e circonferenza della coscia prima e dopo. Modalità di assegnazione, cecità, innesto, tempo dall'intervento e ripartizione dei gruppi non riportati nell'abstract. Letto solo l'abstract.",pop:"20 atleti; età, sesso, sport e numero per gruppo non riportati nell'abstract.",results:"Gruppo con elettrostimolazione a 10 settimane: Lysholm 86,56 ± 11,67; circonferenza della coscia operata 47,15 ± 2,56 cm; flessione attiva 105,12 ± 9,87°; ACL-RSI 84,21 ± 5,32; salto su tre appoggi 264,39 ± 29,36 cm sul lato sano e 178,16 ± 21,26 cm sul lato operato. Valori del gruppo di controllo, differenze, intervalli di confidenza e p non riportati nell'abstract.",concl:"Gli autori: l'elettrostimolazione associata alla riabilitazione dà esiti funzionali superiori alla riabilitazione convenzionale e promette un'applicazione pratica.",limits:"Venti pazienti in due gruppi, assegnazione non descritta · 'superiore' non verificabile: nell'abstract mancano i numeri del confronto · 10 settimane di osservazione, senza rientro allo sport, stabilità o recidive.",perte:"Bianco: riguarda la riabilitazione dopo LCA, non una tua tecnica; l'innesto non è riportato. Non cambia nulla per i tuoi LCA con quadricipite o retto femorale. Non muove le tensioni (la T4 riguarda i criteri di rientro, qui non c'è un criterio). Cosa fare: nulla."},{n:5,mono:"m-jeo",dot:"gray",sec:"res",j:"J Exp Orthop",h:"Rottura del quadricipite: fori transossei angolati a 45° più resistenti di quelli longitudinali, simili alle ancore",v:"Studio biomeccanico su 21 rotule di cadavere (7 per gruppo), gruppo di Münster: carico di rottura 472,7 ± 22,4 N con tre fori transossei angolati contro 344,8 ± 108,8 N con fori longitudinali (p<0,05); le ancore danno 438,9 ± 77,4 N, senza differenza significativa con gli altri due gruppi.",ax:"Michel, Palma Kries, Frank, Raschke, Katthagen, Oeckenpöhler, Kittl, Deichsel, Michel",date:"mar 2026",meta:"studio biomeccanico su cadavere, 21 rotule (7 per gruppo)",pmid:'42899284',doi:'10.1002/jeo2.70695',journal:"Journal of experimental orthopaedics",authors:"Michel NS, Palma Kries LK, Frank A, Raschke MJ, Katthagen JC, Oeckenpöhler S, Kittl C, Deichsel A, Michel PA",design:"Rotule di cadavere assegnate a caso a tre riparazioni del tendine quadricipite: due ancore (SA), tre fori transossei longitudinali (TL) o tre fori transossei angolati anteriormente a 45° (TA), con sutura a quattro fili identica. Densità ossea e spessore corticale misurati in TC. Carico precondizionato, 500 cicli (20-100 N), poi carico fino alla rottura. Esito primario: carico di rottura. Letto solo l'abstract.",pop:"21 rotule umane di cadavere, 7 per gruppo. Età, sesso e densità ossea dei campioni non riportati nell'abstract.",results:"Carico di rottura: TA 472,7 ± 22,4 N contro TL 344,8 ± 108,8 N (p<0,05); SA 438,9 ± 77,4 N, senza differenze significative con TA e TL. Allungamento ciclico: TL 6,22 ± 1,03 mm contro SA 4,42 ± 0,82 mm (p<0,01); TA 5,03 ± 0,73 mm, senza differenza con gli altri. Rigidità senza differenze (p>0,05).",concl:"Gli autori: la tecnica transossea con fori angolati dà carichi di rottura maggiori e meno allungamento della classica longitudinale, con prestazioni confrontabili alle ancore: alternativa valida.",limits:"Cadavere, 7 per gruppo: 'nessuna differenza' fra TA e SA non è equivalenza · stabilità primaria nei primi cicli, non guarigione né ripresa del carico in vivo · densità ossea dei campioni non riportata.",perte:"Bianco: il tendine quadricipite è qui l'estensore rotto riancorato alla rotula, non un innesto per il LCA; non tocca il tuo innesto. Cosa fare: nulla. Nota: il gruppo di Münster compare già nella tua rete (Kittl, proposto nei suggerimenti)."},{n:6,mono:"m-jrs",dot:"gray",sec:"res",j:"J Robot Surg",h:"Protesi robotica con allineamento funzionale: più il mediale è stretto in flessione, più si ruota il femore",v:"Studio osservazionale di un chirurgo (Belo Horizonte) su 65 ginocchia varo: la tensione mediale in flessione si associa alla rotazione femorale scelta (ρ di Spearman 0,571; p<0,001), 0,343° per ogni mm di tensione (R² 0,257). Rilascio lieve in 64/65, asimmetria finale sotto 1 mm in 53/58 (91,4%) in entrambe le posizioni. Non stabilisce vantaggi clinici.",ax:"Temponi, Gomes, de Andrade, do Vale, Soares, Soares, de Carvalho Júnior",date:"ott 2026",meta:"studio osservazionale monocentrico di un chirurgo, 65 ginocchia varo (63 analizzabili)",pmid:'42860454',doi:'10.1007/s11701-026-04037-6',journal:"Journal of robotic surgery",authors:"Temponi EF, Gomes PHO, de Andrade AL, do Vale MJA, Soares MBJ, Soares LFM, de Carvalho Júnior LH",design:"Studio osservazionale di un solo chirurgo sulle 65 ginocchia varo di un database di 89 con TKA robotica ad allineamento funzionale. Tensione mediale definita come gap in flessione laterale meno mediale prima dell'intervento; correlazione e regressione ai minimi quadrati su 63 osservazioni; gap preoperatori, pianificati e finali con denominatori propri; modello esplorativo con posizione coronale e pendenza tibiale. Sistema robotico non nominato nell'abstract. Letto solo l'abstract.",pop:"65 ginocchia varo (63 con dati completi per il modello) di un database di 89; età e sesso non riportati nell'abstract.",results:"Rotazione scelta e tensione mediale: ρ di Spearman 0,571 (p<0,001). Retta: rotazione = 1,93° + 0,343°/mm × tensione (R² 0,257; IC 95% della pendenza 0,194-0,492); pendenza aggiustata 0,296°/mm (IC 95% 0,131-0,460; n=60). Rilascio lieve in 64/65, moderato in 1/65. Asimmetria finale media assoluta 0,38 mm in estensione e 0,29 mm in flessione; sotto 1 mm in 50/60 (83,3%) e 55/59 (93,2%); entro 1 mm in entrambe 53/58 (91,4%).",concl:"Gli autori: maggiore tensione mediale in flessione si associa a maggiore rotazione femorale scelta; rilasci prevalentemente lievi e asimmetria finale piccola. L'equazione descrive le decisioni di un chirurgo e non è una regola chirurgica validata.",limits:"Un solo chirurgo, osservazionale, senza esiti clinici né gruppo di confronto · gli autori stessi non stabiliscono un effetto risparmiatore di rilasci, la superiorità clinica della simmetria sotto 1 mm, la sicurezza femororotulea né un beneficio a lungo termine · denominatori diversi per ogni esito (n=58-65).",perte:"Bianco: protesi totale con robot ad allineamento funzionale, ma il sistema non è nominato nell'abstract e non è dimostrato che sia il VELYS: non direttamente trasferibile. Il dato utile è solo descrittivo (la rotazione scelta segue il gap mediale). Non muove le tensioni. Cosa fare: nulla."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Rev Esp Cir Ortop Traumatol",h:"Femore in una coorte spagnola: riferimenti fissi per la protesi portano al varo nel 74,7% e alla rotazione interna nel 46,1%",v:"Studio trasversale multicentrico su TC di 318 pazienti con artrosi: asse anatomico-meccanico 6,0° ± 0,9°, angolo condilare posteriore-transepicondilare 3,1° ± 1,8°, LDFA nativo 87,3° ± 2,9°. Simulando 5° di valgo dall'asse anatomico e 3° di rotazione esterna dai condili posteriori, il 74,7% dei femori risulta in varo e il 46,1% in rotazione interna rispetto all'asse transepicondilare.",ax:"Pujol, Hinarejos, Pons, Famada, Zumel, Novillo, Erquicia, Leal-Blanquet",date:"ott 2026",meta:"studio trasversale osservazionale multicentrico, 318 TC",pmid:'42901445',doi:'10.1016/j.recot.2026.10.003',journal:"Revista espanola de cirugia ortopedica y traumatologia",authors:"Pujol O, Hinarejos P, Pons A, Famada E, Zumel A, Novillo M, Erquicia J, Leal-Blanquet J",design:"Studio trasversale multicentrico (Vall d'Hebron, Hospital del Mar e Manresa, Spagna): TC preoperatorie di 318 pazienti con artrosi per misurare l'angolo asse anatomico-meccanico (AA-MA), l'angolo condilare posteriore-transepicondilare (PCA-TEA) e l'angolo laterale distale del femore (LDFA). Simulazione del componente femorale a 5° di valgo dall'asse anatomico e a 3° di rotazione esterna dai condili posteriori, confrontata con il bersaglio dell'allineamento meccanico. Letto solo l'abstract.",pop:"318 pazienti di una coorte spagnola con artrosi del ginocchio; età, sesso e gravità non riportati nell'abstract.",results:"AA-MA 6,0° ± 0,9°; PCA-TEA 3,1° ± 1,8°; LDFA nativo 87,3° ± 2,9°. Con la simulazione, 74,7% dei componenti in varo e 46,1% in rotazione interna rispetto alla TEA; l'allineamento meccanico produrrebbe un'interlinea più in varo della nativa nel 78,1%. Fuori dai range abituali: AA-MA fuori da 5-7° nel 6,7%, PCA-TEA sotto 2° o sopra 4° nel 41,8%, LDFA fuori da 85-90° nel 30,6%. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la variabilità dell'anatomia femorale è notevole; posizionare il componente con i soli riferimenti AA e PCA si associa a deviazioni dall'allineamento meccanico previsto, soprattutto varo e rotazione interna.",limits:"Simulazione su TC, nessun esito clinico né impianto reale · una sola coorte nazionale con artrosi, valori non trasferibili ad altre popolazioni · il bersaglio 'meccanico' è una scelta, non un dato.",perte:"Bianco: protesi totale, non una tua tecnica in senso stretto. Il lavoro non nomina alcun robot: il dato vale per chi posiziona il femore con riferimenti fissi, e conferma che l'anatomia varia abbastanza da far preferire una misura individuale; con il VELYS non c'è un dato diretto. Non muove le tensioni. Cosa fare: nulla."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Indian J Orthop",h:"Rottura del quadricipite dopo protesi: 11 studi, 132 ginocchia, complicanze nel 17,8%, nessun trattamento standard",v:"Revisione sistematica PRISMA di 11 studi (10 retrospettivi, 1 prospettivo): 132 ginocchia, età media 54 anni, 60% donne. Sutura semplice in 49, V-Y in 46, rinforzo con rete in 10, ricostruzione con innesto in 19, trattamento conservativo in 8. Complicanze 17,8%, le più comuni la nuova rottura e l'infezione; intervalli non riportati.",ax:"Choudhury, Gupta, Gaurav, Kanwar, Pranav, Kalia",date:"ago 2026",meta:"revisione sistematica PRISMA di studi osservazionali, livello III, 11 studi, 132 ginocchia",pmid:'42894534',doi:'10.1007/s43465-026-01913-z',journal:"Indian journal of orthopaedics",authors:"Choudhury AK, Gupta K, Gaurav A, Kanwar S, Pranav J, Kalia RB",design:"Revisione sistematica (PRISMA) su PubMed, Embase e Scopus delle tecniche di trattamento, degli esiti e delle complicanze della rottura del tendine quadricipite dopo protesi totale. Registro del protocollo, valutazione del rischio di bias e metodo di sintesi non riportati nell'abstract. Letto solo l'abstract.",pop:"11 studi, 132 ginocchia in 126 pazienti; età media 54 anni, donne 60%; 35 ginocchia con rottura parziale (5 studi); causa più comune la caduta.",results:"Gestione: conservativa in 8 ginocchia (7 rotture parziali e 1 completa); sutura semplice in 49, V-Y in 46, rinforzo con rete in 10, ricostruzione con innesto in 19. Complicanze complessive 17,8%, con nuova rottura e infezione le più frequenti. Intervalli di confidenza e confronti fra tecniche non riportati nell'abstract.",concl:"Gli autori: riparazione o ricostruzione migliorano in modo costante il deficit di estensione e i punteggi riferiti, la flessione è variabile; V-Y e innesto sono usati soprattutto nei casi cronici; servono studi multicentrici per un protocollo standard.",limits:"10 studi su 11 retrospettivi, serie piccole e probabilmente sovrapposte nelle tecniche · nessun confronto diretto fra le tecniche, quindi nessuna indicazione su quale scegliere · complicanza rara, quindi stime imprecise.",perte:"Bianco: complicanza rara della protesi totale, non tocca il tuo innesto né il VELYS. Cosa fare: nulla. Non muove le tensioni."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"J Rehabil Med",h:"Dolore femororotuleo negli adolescenti: la pliometria in acqua riduce dolore e disabilità più degli esercizi convenzionali",v:"RCT a due bracci su 56 adolescenti di 10-18 anni (Arabia Saudita), 12 settimane, 45 minuti due volte alla settimana. Meno dolore con la pliometria in acqua (p=0,004; η²p=0,14) e più forza di quadricipite e ischiocrurali a 120°/s e 180°/s (p=0,006-0,023), minore disabilità funzionale (p=0,03). Le medie dei gruppi non sono nell'abstract.",ax:"Alotaibi, Elnaggar, Alhowimel, Alrawaili, Elnegamy, Alfeheid, Basha, Kamel, Aloraini, Alsultan, Alharbi, Elfakharany",date:"ott 2026",meta:"RCT a due bracci, 56 adolescenti, 12 settimane",pmid:'42895359',doi:'10.2340/jrm.v58.46495',journal:"Journal of rehabilitation medicine",authors:"Alotaibi MA, Elnaggar RK, Alhowimel AS, Alrawaili SM, Elnegamy TE, Alfeheid HA, Basha MA, Kamel FH, Aloraini SM, Alsultan F, Alharbi A, Elfakharany MS",design:"RCT a due bracci: pliometria in acqua contro esercizi convenzionali, 45 minuti due volte alla settimana per 12 settimane. Dolore, coppia isocinetica di quadricipite e ischiocrurali a 120°/s e 180°/s, disabilità funzionale e qualità di vita correlata alla salute, prima e dopo. ANOVA a modelli misti. Modalità di randomizzazione e cecità non riportate nell'abstract. Letto solo l'abstract.",pop:"56 adolescenti con dolore femororotuleo, 10-18 anni; ripartizione per gruppo, sesso e gravità non riportate nell'abstract.",results:"Interazione gruppo × tempo: dolore p=0,004 (η²p 0,14); coppia del quadricipite a 120°/s p=0,006 (η²p 0,13) e a 180°/s p=0,008 (0,12); ischiocrurali a 120°/s p=0,007 (0,13) e a 180°/s p=0,023 (0,09); disabilità funzionale p=0,03 (0,08); qualità di vita p=0,023 (0,09). Medie dei gruppi, intervalli di confidenza e soglie minime clinicamente rilevanti non riportati nell'abstract.",concl:"Gli autori: la pliometria in acqua riduce dolore e disabilità e migliora forza e qualità di vita negli adolescenti con dolore femororotuleo: un'aggiunta utile alla riabilitazione conservativa.",limits:"Effetti da piccoli a medi (η²p 0,08-0,14), senza medie né soglie clinicamente rilevanti: 'dominanza terapeutica' è un'espressione più forte dei dati · 12 settimane, nessun follow-up successivo · età 10-18 anni, in parte sotto i 14 anni della tua popolazione.",perte:"Bianco: dolore femororotuleo conservativo, non una tua tecnica. Parte dei pazienti ha meno di 14 anni, quindi non è tutto trasferibile ai tuoi. Cosa fare: nulla. Non muove le tensioni."}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Giovedì 22 ottobre. Oggi nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo di dispositivi nuovo rispetto a ieri, nessuna linea guida o consensus nuovo che tocchi la tua pratica e nessuna ritrattazione che ti riguardi. Il lavoro del giorno è una revisione sistematica coreana, di Seul, sui fattori che predicono l'esito dopo la riparazione della cartilagine del ginocchio: trentuno report inclusi, ma la somma dei pazienti, tredicimilaventidue, conta più volte le stesse coorti. Su trentasette analisi, ventinove hanno un rischio di bias alto e otto moderato, nessuna basso. Dopo le microfratture un'età maggiore si associa a esiti peggiori in due analisi aggiustate, per esempio odds ratio zero virgola sei uno per il miglioramento clinicamente rilevante a ventiquattro mesi, ma gli intervalli di confidenza non sono riportati; per la dimensione della lesione i risultati cambiano da un esito all'altro. Nessun fattore è confermato in modo costante fra le procedure, e gli autori dicono che le prove non sostengono soglie universali di età, indice di massa corporea o dimensione del difetto. L'AMIC con Chondro-Gide e il minced cartilage con AutoCart non sono nominati: la categoria più vicina è la stimolazione midollare con un adiuvante biologico; ho letto il testo completo. Poi otto lavori. Osteotomia tibiale alta di apertura, coorte giapponese di duecentosettantaquattro ginocchia seguite in media dodici anni: conversione in protesi nel ventidue virgola due per cento dei gradi quattro contro il sei virgola nove per cento dei gradi due e tre, con una regressione nei gradi due e tre basata su circa otto eventi. Una nota tecnica sul menisco laterale discoide di Wrisberg: la radice ricreata con un'ancora senza nodi per risparmiare la fisi, senza esiti riportati. Elettrostimolazione dopo il crociato in venti atleti: studio troppo piccolo, e nell'abstract mancano i dati dei controlli. Poi cinque lavori bianchi o meno vicini: il rifissaggio transosseo del tendine quadricipite rotto su cadavere, con fori angolati simili alle ancore; la protesi robotica con allineamento funzionale e la rotazione del femore, con il sistema non nominato; l'anatomia femorale in una coorte spagnola; la rottura del quadricipite dopo protesi in una revisione sistematica; e la pliometria in acqua negli adolescenti con dolore femororotuleo. Tensioni: nessuna si è mossa; la quinta, sul minced cartilage, è toccata di striscio.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Giovedì ventidue ottobre. Nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo nuovo, nessun consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Una revisione sistematica coreana sui fattori che predicono l'esito dopo la riparazione della cartilagine del ginocchio. Trentuno report, senza metanalisi."}, {"chi": "B", "t": "E cosa trova?"}, {"chi": "A", "t": "Dopo le microfratture un'età maggiore si associa a esiti peggiori in due analisi aggiustate, ma gli intervalli di confidenza non sono riportati. Per la dimensione della lesione i risultati cambiano da un esito all'altro, e fra le altre procedure non c'è un fattore costante."}, {"chi": "B", "t": "Quanto ci si può fidare?"}, {"chi": "A", "t": "Poco. Su trentasette analisi, ventinove hanno rischio di bias alto e nessuna basso, e le coorti si sovrappongono: la somma di tredicimilaventidue non è un numero di pazienti. Gli autori stessi dicono che le prove non sostengono soglie di età, peso o dimensione del difetto."}, {"chi": "B", "t": "Quindi per il tuo AMIC e per il minced cartilage?"}, {"chi": "A", "t": "Nessuno dei due è nominato. La categoria più vicina è la stimolazione midollare con un adiuvante biologico, quindi non è direttamente trasferibile. Il consiglio pratico è non usare età o peso come criterio di esclusione."}, {"chi": "B", "t": "Gli altri lavori?"}, {"chi": "A", "t": "L'osteotomia tibiale d'apertura a dodici anni: la protesi serve nel ventidue per cento dei gradi quattro contro il sette per cento dei gradi due e tre, ma nel secondo gruppo gli eventi sono circa otto e la regressione è solo esplorativa. Poi una nota tecnica per il menisco discoide che ricrea la radice con un'ancora, senza esiti."}, {"chi": "B", "t": "E sulla protesi e sul quadricipite?"}, {"chi": "A", "t": "Tre lavori bianchi: i fori angolati nella rotula tengono come le ancore nei cadaveri, la rotazione del femore nella protesi robotica segue la tensione mediale ma il sistema non è nominato, e in una coorte spagnola i riferimenti fissi portano spesso il femore in varo. Nessuna tensione si è mossa."}];
